import{G as e,W as t,n,rt as r}from"./chunks/framework.OKfwtFe7.js";var i=JSON.parse(`{"title":"应用场景与各语言落地","description":"","frontmatter":{},"headers":[],"relativePath":"research/applications.md","filePath":"research/applications.md","lastUpdated":1791561689000}`),a={name:`research/applications.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="应用场景与各语言落地" tabindex="-1">应用场景与各语言落地 <a class="header-anchor" href="#应用场景与各语言落地" aria-label="Permalink to “应用场景与各语言落地”">​</a></h1><p>模式最终要在具体语言里写出来。这一篇按&quot;场景 → 模式 → 落地 API&quot;排，说明站内正文里的例子来自哪里，以及为什么某些模式在有的语言里根本不用写。</p><h2 id="对象创建与装配" tabindex="-1">对象创建与装配 <a class="header-anchor" href="#对象创建与装配" aria-label="Permalink to “对象创建与装配”">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>模式</th><th>Java</th><th>C++</th><th>Go</th><th>C# / .NET</th></tr></thead><tbody><tr><td>一次拿到一族相关对象</td><td><a href="/hello-design-patterns/creational/abstract-factory">抽象工厂</a></td><td>工厂接口 + 配置切换实现</td><td>抽象工厂类 + 模板</td><td>接口字面量表</td><td><code>IAbstractFactory</code> + DI 容器</td></tr><tr><td>分步拼复杂对象</td><td><a href="/hello-design-patterns/creational/builder">建造者</a></td><td>桶构造器</td><td>链式 <code>builder()</code> 返回引用</td><td>函数式选项 <code>WithXxx</code></td><td>指定属性初始化</td></tr><tr><td>只留一个实例</td><td><a href="/hello-design-patterns/creational/singleton">单例</a></td><td><code>enum</code> 单例或静态持有</td><td>局部静态对象（线程安全）</td><td>包级 <code>sync.Once</code></td><td>线程安全的懒加载静态字段</td></tr><tr><td>复用昂贵对象</td><td><a href="/hello-design-patterns/creational/object-pool">对象池</a></td><td>数据库连接池、<code>HikariCP</code></td><td>线程池队列</td><td>channel 当队列</td><td><code>ObjectPool&lt;T&gt;</code></td></tr></tbody></table><p>依赖装配这件事在 Java/C# 里由容器做，对应<a href="/hello-design-patterns/structural/dependency-injection">依赖注入</a>与<a href="/hello-design-patterns/creational/service-locator">服务定位器</a>。Go 没有容器，装配写在 <code>main</code> 里，所以 Go 示例不出现 DI 框架，只出现&quot;把接口当参数传进去&quot;。</p><h2 id="接口适配与访问控制" tabindex="-1">接口适配与访问控制 <a class="header-anchor" href="#接口适配与访问控制" aria-label="Permalink to “接口适配与访问控制”">​</a></h2><ul><li><strong>对接第三方 SDK</strong> → <a href="/hello-design-patterns/structural/adapter">适配器</a>。站内示例按&quot;目标接口由我方定义、适配器包一层&quot;写，这与 Java 的 <code>InputStreamReader</code>、C++ 的迭代器适配器同构。</li><li><strong>给子系统一个薄入口</strong> → <a href="/hello-design-patterns/structural/facade">外观</a>。</li><li><strong>控制访问、加缓存或权限</strong> → <a href="/hello-design-patterns/structural/proxy">代理</a>的四个变体。Java 用 <code>java.lang.reflect.Proxy</code> 做动态代理，C++ 用包装类，Go 用接口包装，JavaScript 直接用语言内置的 <code>Proxy</code> 对象 [S28]。</li><li><strong>给对象加职责而不改类</strong> → <a href="/hello-design-patterns/structural/decorator">装饰</a>。Java 的 <code>java.io</code> 输入输出流链是标准例子，C++ 对应 <code>std::istreambuf_iterator</code> 那层包装，C# 对应 <code>Stream</code> 的包装类。</li><li><strong>接口要跨进程</strong> → <a href="/hello-design-patterns/structural/remote-facade">远程外观与数据传输对象</a>。Java 落地是 Spring MVC 的 controller 方法签名（EJB Session Facade 是前身），Go 是手写 service struct 加请求/响应结构体，gRPC 的 <code>message</code> 定义就是 DTO。</li></ul><h2 id="行为与流程" tabindex="-1">行为与流程 <a class="header-anchor" href="#行为与流程" aria-label="Permalink to “行为与流程”">​</a></h2><ul><li><strong>算法可换</strong> → <a href="/hello-design-patterns/behavioral/strategy">策略</a>。Java 传 <code>Function</code>，C++ 传 <code>std::function</code> 或模板参数，Go 用小接口或函数类型，TypeScript 传函数属性。四者都不需要为每个算法建一个子类。</li><li><strong>流程步骤固定、个别步骤可换</strong> → <a href="/hello-design-patterns/behavioral/template-method">模板方法</a>。Java/C++ 用抽象基类的可覆盖方法；Go 没有抽象类，用接口加结构体嵌入表达同一个骨架，站内 Go 示例走的就是这条路。</li><li><strong>事件通知</strong> → <a href="/hello-design-patterns/behavioral/observer">观察者</a>。落地位置分别是 <code>EventTarget</code> [S28]、Qt 的 signal/slot、Rx 风格流、Go 的 channel 广播。Go 标准库没有观察者类，站内 Go 示例用接口实现，流水线与取消的写法见官方博客 [S21]。</li><li><strong>请求逐级处理</strong> → <a href="/hello-design-patterns/behavioral/chain-of-responsibility">责任链</a>。中间件栈（Servlet Filter、Koa 中间件、Go <code>http.Handler</code> 包装）是它在 Web 框架里的形态。</li><li><strong>状态决定行为</strong> → <a href="/hello-design-patterns/behavioral/state">状态</a>。TCP 连接状态机、订单状态流转、播放器状态是三个常用例子。</li><li><strong>对象结构上的多种操作</strong> → <a href="/hello-design-patterns/behavioral/visitor">访问者</a>。经典形态是 <code>accept/visit</code> 双分派，站内正文用 Java 示例展开；C++ 没有双分派语法，惯用 <code>std::variant</code> 加 <code>std::visit</code> 把分支交给标准库做，不再手写分派表。</li></ul><h2 id="并发与异步" tabindex="-1">并发与异步 <a class="header-anchor" href="#并发与异步" aria-label="Permalink to “并发与异步”">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>模式</th><th>标准落地</th></tr></thead><tbody><tr><td>固定规模的后台任务</td><td><a href="/hello-design-patterns/concurrency/thread-pool">线程池</a></td><td><code>ThreadPoolExecutor</code> / <code>std::thread</code> 池 / goroutine 池</td></tr><tr><td>读多写少</td><td><a href="/hello-design-patterns/concurrency/read-write-lock">读写锁</a></td><td><code>ReentrantReadWriteLock</code> / <code>std::shared_mutex</code> / <code>sync.RWMutex</code></td></tr><tr><td>CPU 密集任务分片</td><td><a href="/hello-design-patterns/concurrency/work-stealing">工作窃取</a></td><td><code>ForkJoinPool</code> / 工作窃取 deque</td></tr><tr><td>缓冲速度差</td><td><a href="/hello-design-patterns/concurrency/producer-consumer">生产者-消费者</a></td><td><code>BlockingQueue</code> / 有缓冲 channel</td></tr><tr><td>单线程处理 I/O</td><td><a href="/hello-design-patterns/concurrency/event-loop">事件循环</a>、<a href="/hello-design-patterns/concurrency/reactor">反应器</a></td><td>Node.js 事件循环、Netty、<code>libuv</code></td></tr><tr><td>异步结果占位</td><td><a href="/hello-design-patterns/concurrency/future">Future</a></td><td><code>CompletableFuture</code> / <code>std::future</code> / <code>Promise</code></td></tr><tr><td>惰性安全初始化</td><td><a href="/hello-design-patterns/concurrency/double-checked-locking">双重检查锁定</a></td><td><code>volatile</code> + 同步块 / <code>std::call_once</code> / <code>sync.Once</code></td></tr></tbody></table><p>这一栏的术语以 Java SE <code>java.util.concurrent</code> 文档 [S19] 为准，C++ 部分对照 Core Guidelines 的资源管理建议 [S20]，Go 部分对照官方文档 [S21]。</p><h2 id="数据与分层" tabindex="-1">数据与分层 <a class="header-anchor" href="#数据与分层" aria-label="Permalink to “数据与分层”">​</a></h2><ul><li><strong>表和对象的阻抗失配</strong> → <a href="/hello-design-patterns/other/orm">ORM</a>：Hibernate、Entity Framework、Django ORM。</li><li><strong>业务逻辑写在哪一层</strong> → <a href="/hello-design-patterns/other/transaction-script">事务脚本</a> 与<a href="/hello-design-patterns/anti-patterns/anemic-domain-model">贫血模型</a>对照，来源是企业应用架构模式 [S5] 与 Martin 的 bliki [S26]。</li><li><strong>状态可回放</strong> → <a href="/hello-design-patterns/other/event-sourcing">事件溯源</a>：追加事件日志 + 快照，与<a href="/hello-design-patterns/behavioral/memento">备忘录</a>的区别是前者记过程、后者记瞬间。</li><li><strong>前后端职责划分</strong> → <a href="/hello-design-patterns/other/mvc">MVC</a>、<a href="/hello-design-patterns/other/mvvm">MVVM</a>：Spring MVC、iOS SwiftUI、Vue 的组件模型。</li></ul><h2 id="分布式与云上" tabindex="-1">分布式与云上 <a class="header-anchor" href="#分布式与云上" aria-label="Permalink to “分布式与云上”">​</a></h2><p>熔断最初出自 Release It! [S12]，现在是网关与 RPC 客户端的标配（Resilience4j、Polly、Sentinel 的熔断器都是同一个模型）：统计窗口内失败率超阈值就直接失败，不再打下游。本次新增<a href="/hello-design-patterns/evolution/circuit-breaker">熔断器</a>用 Go 与 Java 两版实现。</p><p>微服务方向的 API 网关、Saga、服务发现来自 Richardson 那本书 [S13]，Kubernetes 上的模式来自 Kubernetes Patterns [S15]，这两批条目记在差异表里，暂不新增，理由是它们属于分布式系统设计而非本仓&quot;设计模式&quot;的现有口径。</p><h2 id="多语言落地的差异-站内写法约定" tabindex="-1">多语言落地的差异（站内写法约定） <a class="header-anchor" href="#多语言落地的差异-站内写法约定" aria-label="Permalink to “多语言落地的差异（站内写法约定）”">​</a></h2><ol><li>需要&quot;多态&quot;的地方：Java/C#/C++ 用接口或抽象类，Go 用小接口加嵌入，站内示例按语言习惯写，不跨语言硬译。</li><li>需要&quot;复用逻辑&quot;的地方：继承在 Go 与函数式语言里不存在，统一改写成组合，见<a href="/hello-design-patterns/evolution/composition-over-inheritance">组合式设计</a>。</li><li>单例的代价（全局状态、测试困难）在 Java/C# 上最明显，在 Go 里包级变量同样可测性差，站内单例篇与反模式篇各写一半。</li><li>线程模型差异决定了并发篇的示例：Java 用线程池，C++ 用 <code>std::jthread</code> 与 <code>std::stop_token</code>，Go 用 goroutine 加 channel。</li></ol>`,19)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};